fn check(name: &str, got: &[i64], want: &[i64]) {
    assert_eq!(got.len(), want.len(), "{name}: length");
    for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
        assert_eq!(g, w, "{name}[{i}]: got {g}, mirror says {w}");
    }
}

